<?php
declare(strict_types=1);namespace BizStock\Repositories;
final readonly class AnalyticsRepository
{
 public function __construct(private \PDO $pdo){}
 public function movementSummary(string $from,string $until,string $group,int $limit,int $offset):array{
  // Reversal is an offset in the ORIGINAL direction on the reversal's timestamp.
  $effectiveType='COALESCE(o.type,t.type)';$signed='CASE WHEN t.correction_of_transaction_id IS NULL THEN CAST(t.quantity AS DECIMAL(30,0)) ELSE -CAST(t.quantity AS DECIMAL(30,0)) END';
  $events="SELECT p.product_id,p.product_name,p.category_id,c.category_name,COALESCE(t.unit_code,'unspecified') AS unit_code,{$effectiveType} AS effective_type,{$signed} AS signed_quantity FROM transactions t JOIN products p ON p.product_id=t.product_id JOIN categories c ON c.category_id=p.category_id LEFT JOIN transactions o ON o.transaction_id=t.correction_of_transaction_id WHERE t.transaction_date>=? AND t.transaction_date<? AND ((CASE WHEN t.correction_of_transaction_id IS NULL THEN t.movement_kind ELSE o.movement_kind END)='ordinary' OR ((CASE WHEN t.correction_of_transaction_id IS NULL THEN t.movement_kind ELSE o.movement_kind END) IS NULL AND COALESCE(o.type,t.type)='OUT')) AND NOT EXISTS (SELECT 1 FROM operation_requests op WHERE op.operation_kind='product.create' AND op.transaction_id=COALESCE(t.correction_of_transaction_id,t.transaction_id))";
  $key=$group==='category'?'e.category_id':($group==='unit'?'e.unit_code':'e.product_id');$name=$group==='category'?'e.category_name':($group==='unit'?'e.unit_code':'e.product_name');$unitSelect=$group==='top'?"CASE WHEN COUNT(DISTINCT e.unit_code)=1 THEN MIN(e.unit_code) ELSE 'unspecified' END":'e.unit_code';$groupSql=$key.','.$name.($group==='top'?'':',e.unit_code');
  $sql="SELECT {$key} AS group_id,{$name} AS group_name,{$unitSelect} AS unit_code,CAST(SUM(CASE WHEN e.effective_type='IN' THEN e.signed_quantity ELSE 0 END) AS CHAR) AS units_in,CAST(SUM(CASE WHEN e.effective_type='OUT' THEN e.signed_quantity ELSE 0 END) AS CHAR) AS units_out,CAST(SUM(CASE WHEN e.effective_type='IN' THEN e.signed_quantity ELSE -e.signed_quantity END) AS CHAR) AS net_units FROM ({$events}) e GROUP BY {$groupSql}";
  $sort=$group==='top'?'CAST(units_out AS DECIMAL(30,0)) DESC,group_id ASC,unit_code ASC':'group_id ASC,unit_code ASC';$having=$group==='top'?" HAVING SUM(CASE WHEN e.effective_type='OUT' THEN e.signed_quantity ELSE 0 END)>0":'';
  $count=$this->pdo->prepare('SELECT COUNT(*) FROM ('.$sql.$having.') summary_rows');$count->execute([$from,$until]);$total=(int)$count->fetchColumn();
  $q=$this->pdo->prepare('SELECT * FROM ('.$sql.$having.') summary_rows ORDER BY '.$sort.' LIMIT ? OFFSET ?');$q->bindValue(1,$from);$q->bindValue(2,$until);$q->bindValue(3,$limit,\PDO::PARAM_INT);$q->bindValue(4,$offset,\PDO::PARAM_INT);$q->execute();return ['data'=>$q->fetchAll(),'total'=>$total];
 }
 public function inactive(string $from,string $until,int $limit,int $offset):array{
  $where=" WHERE p.is_active=1 AND p.created_at<? AND NOT EXISTS (SELECT 1 FROM transactions t LEFT JOIN transactions o ON o.transaction_id=t.correction_of_transaction_id WHERE t.product_id=p.product_id AND t.transaction_date>=? AND t.transaction_date<? AND COALESCE((CASE WHEN t.correction_of_transaction_id IS NULL THEN t.movement_kind ELSE o.movement_kind END),'ordinary') NOT IN ('opening','adjustment') AND NOT EXISTS (SELECT 1 FROM operation_requests op WHERE op.operation_kind='product.create' AND op.transaction_id=COALESCE(t.correction_of_transaction_id,t.transaction_id)))";
  $q=$this->pdo->prepare('SELECT COUNT(*) FROM products p'.$where);$q->execute([$until,$from,$until]);$total=(int)$q->fetchColumn();$q=$this->pdo->prepare('SELECT p.product_id,p.sku,p.product_name,p.quantity,p.unit_code FROM products p'.$where.' ORDER BY p.product_id LIMIT ? OFFSET ?');foreach([$until,$from,$until] as $i=>$v)$q->bindValue($i+1,$v);$q->bindValue(4,$limit,\PDO::PARAM_INT);$q->bindValue(5,$offset,\PDO::PARAM_INT);$q->execute();return ['data'=>$q->fetchAll(),'total'=>$total];
 }
 public function unclassified(string $from,string $until):int{$q=$this->pdo->prepare("SELECT COUNT(*) FROM transactions t LEFT JOIN transactions o ON o.transaction_id=t.correction_of_transaction_id WHERE t.transaction_date>=? AND t.transaction_date<? AND (CASE WHEN t.correction_of_transaction_id IS NULL THEN t.movement_kind ELSE o.movement_kind END) IS NULL AND COALESCE(o.type,t.type)='IN' AND NOT EXISTS (SELECT 1 FROM operation_requests op WHERE op.operation_kind='product.create' AND op.transaction_id=COALESCE(t.correction_of_transaction_id,t.transaction_id))");$q->execute([$from,$until]);return (int)$q->fetchColumn();}
 public function quantitiesByUnit():array{return $this->pdo->query('SELECT unit_code,CAST(SUM(CAST(quantity AS DECIMAL(30,0))) AS CHAR) AS quantity FROM products WHERE is_active=1 GROUP BY unit_code ORDER BY unit_code')->fetchAll();}
}
